  (4034, 19253, 'Bo’ku likas ng-ogo siokoku', 'likas', 'rupiah wanted to return home quickly…', 'Rupiah wanted to return home quickly…', NULL),
  (4035, 19257, '…pe-limpas lagi dela', 'limpas', 'itu, oleh', 'At that time, by Allah', NULL),
